syntax:
if (condition1 && condition2)   // AND: both must be true
    statement;

if (condition1 || condition2)   // OR: at least one must be true
    statement;

if (!condition)                 // NOT: true when condition is false
    statement;

if (x >= 1 && x <= 10)          // range check: write both sides
    statement;

if ((a || b) && c)              // brackets show the order clearly
    statement;

