#include <iostream>
using namespace std;

int main() {
    int age;
    bool hasCNIC;
    cout << "Enter age: ";
    cin >> age;
    cout << "Has CNIC (1 = yes, 0 = no): ";
    cin >> hasCNIC;
    if (age >= 18 && hasCNIC) {
        cout << "You can vote." << endl;
    } else {
        cout << "You cannot vote." << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

bool isBig(int n) {
    cout << "isBig runs" << endl;
    return n > 10;
}

int main() {
    bool a = false;
    if (a && isBig(20)) {
        cout << "First" << endl;
    }
    cout << "After first" << endl;
    if (!a || isBig(20)) {
        cout << "Second" << endl;
    }
    if (a || isBig(20)) {
        cout << "Third" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int year;
    cout << "Enter year: ";
    cin >> year;
    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        cout << year << " is a leap year." << endl;
    } else {
        cout << year << " is not a leap year." << endl;
    }
    return 0;
}

